INSERT INTO modules_meta (id, nombre, icon, descripcion, gestion, observacion, sla_dias, issues) VALUES ('reembolsos', 'Reembolsos', '💳', 'Solicitudes de reembolso de gastos médicos particulares ingresadas vía Call Center o formulario directo.', '88% de los casos gestionados — 3 solicitudes sin gestión registrada.', 'El servicio “Salud Mental Online” concentra la mayoría de las solicitudes; 5 casos permanecen pendientes.', 14, '[{"t": "Fecha de ingreso en blanco", "c": 170, "sev": "warning"}, {"t": "Fecha de ingreso en blanco + cita futura", "c": 6, "sev": "serious"}, {"t": "Fecha de cita posterior al ingreso", "c": 7, "sev": "critical"}]'::jsonb);
INSERT INTO modules_meta (id, nombre, icon, descripcion, gestion, observacion, sla_dias, issues) VALUES ('informes', 'Informes Médicos', '📄', 'Solicitudes de informes, certificados y licencias médicas (LM) gestionadas por el equipo.', '60% de los registros fueron ingresados directamente por el paciente, sin intervención de ejecutivo.', 'Traumatología concentra 59% del volumen. El motivo “rechazo de licencia médica” es el más recurrente.', 10, '[{"t": "Fecha de formulario futura", "c": 55, "sev": "serious"}, {"t": "Atención posterior al formulario", "c": 52, "sev": "critical"}, {"t": "Formulario futuro + término LM anterior al inicio", "c": 2, "sev": "critical"}, {"t": "Término de licencia médica futuro", "c": 2, "sev": "warning"}, {"t": "Término de licencia anterior al inicio", "c": 1, "sev": "critical"}, {"t": "Atención futura + posterior al formulario", "c": 1, "sev": "critical"}, {"t": "Formulario futuro + término futuro", "c": 1, "sev": "serious"}]'::jsonb);
INSERT INTO modules_meta (id, nombre, icon, descripcion, gestion, observacion, sla_dias, issues) VALUES ('otras', 'Otras Solicitudes', '🗂️', 'Solicitudes diversas: recetas, órdenes médicas, certificados y confirmaciones diagnósticas.', '61% de los casos no tiene gestión BO registrada.', '“Receta médica” es el motivo más frecuente, con 273 solicitudes.', 10, '[{"t": "Fecha de formulario futura", "c": 105, "sev": "serious"}, {"t": "Atención posterior al formulario", "c": 81, "sev": "critical"}, {"t": "Formulario futuro + atención futura", "c": 2, "sev": "critical"}]'::jsonb);
INSERT INTO modules_meta (id, nombre, icon, descripcion, gestion, observacion, sla_dias, issues) VALUES ('cd', 'CD Pendiente', '🏥', 'Confirmaciones diagnósticas (CD) pendientes de agendamiento en centros presenciales.', '83% de los casos gestionado por un solo ejecutivo (Raquel).', '61 solicitudes sin gestión registrada; el volumen tuvo un pico en abril 2026.', 10, '[{"t": "Fecha de formulario futura", "c": 66, "sev": "serious"}, {"t": "Atención posterior al formulario", "c": 46, "sev": "critical"}]'::jsonb);
INSERT INTO causas (sev, h, p, s, orden) VALUES ('critical', 'Atención no anterior al ingreso (325 casos)', 'Se validó, módulo por módulo, que la “fecha de atención” sea estrictamente anterior a la fecha de ingreso/formulario. 325 registros no cumplen la regla: 18 en Reembolsos, 63 en Informes Médicos, 190 en Otras Solicitudes y 54 en CD Pendiente (137 de ellos son el mismo día exacto, y 188 quedaron con la atención registrada después del ingreso). Solo 34 se explican por el mismo problema de día/mes invertido; el resto no tiene una corrección automática confiable.', 'Aclarar en el formulario si el campo debe registrar la última atención ya ocurrida o la próxima atención agendada, y restringir el campo a un selector de fecha con validación (fecha de atención ≤ fecha de ingreso). El detalle caso a caso, con la corrección sugerida cuando aplica, está disponible en “Secuencia de fechas” dentro de cada módulo.', 0);
INSERT INTO causas (sev, h, p, s, orden) VALUES ('critical', 'Fecha de ingreso con día y mes invertidos (231 casos)', '231 solicitudes (58 en Informes Médicos, 107 en Otras Solicitudes, 66 en CD Pendiente) quedaron con una “Fecha respuesta formulario” en el futuro (septiembre a diciembre de 2026). Se probó matemáticamente invirtiendo día y mes de cada una de las 231 fechas: el 100% cae dentro de un rango coherente con el resto de la base (enero a agosto de 2026). Esto confirma que no son datos inventados ni errores aislados, sino un problema sistemático de formato: el día y el mes se están grabando invertidos (DD/MM leído como MM/DD, o viceversa) cada vez que el día es 12 o menor — el único caso en que la inversión es posible sin generar una fecha inválida. Reembolsos no presenta este problema porque no usa el mismo campo de fecha automática del formulario.', '1) En el formulario (Google Forms u otro), cambiar el campo de fecha de “texto corto” a un campo de tipo Fecha con selector de calendario — elimina la ambigüedad de raíz. 2) Si el dato llega a Google Sheets/Excel vía una integración o pegado automático, revisar la configuración regional de la hoja (Archivo → Configuración → Configuración regional = Chile) para que el formato se interprete siempre como DD/MM/AAAA. 3) Agregar una validación que rechace o marque cualquier fecha de ingreso posterior al día actual. 4) Corregir retroactivamente los 231 registros invirtiendo día y mes — el detalle con la fecha corregida sugerida está disponible en cada módulo, en “Ingreso con fecha futura” dentro de Cumplimiento de SLA.', 1);
INSERT INTO causas (sev, h, p, s, orden) VALUES ('warning', 'Fechas de ingreso en blanco (Reembolsos)', '176 registros de Reembolsos no tienen fecha de ingreso, lo que impide ordenar los casos cronológicamente o medir tiempos de respuesta.', 'Hacer obligatorio el campo de fecha en el formulario de Reembolsos y completar retroactivamente los registros históricos con la fecha disponible más cercana (cita o pago).', 2);
INSERT INTO causas (sev, h, p, s, orden) VALUES ('critical', 'Término de licencia médica anterior al inicio', 'En Informes Médicos existen casos donde la fecha de término de la licencia es anterior a la fecha de inicio — un error de digitación al traspasar los datos de la licencia.', 'Agregar validación en el formulario: la fecha de término no puede guardarse si es anterior a la fecha de inicio.', 3);
